def num_splits_heuristic(batch_nheads_mblocks: int, num_sms: int, num_n_blocks: int, max_splits: int = 128) -> int:
    """Exact port of flash-attn 2.8.3 num_splits_heuristic (flash_api.cpp)."""
    if batch_nheads_mblocks >= 0.8 * num_sms:
        return 1
    max_splits = min(max_splits, num_sms, num_n_blocks)
    eff = [0.0] * (max_splits + 1)
    best = 0.0
    for s in range(1, max_splits + 1):
        if s > 1 and math.ceil(num_n_blocks / s) == math.ceil(num_n_blocks / (s - 1)):
            continue
        n_waves = batch_nheads_mblocks * s / num_sms
        eff[s] = n_waves / math.ceil(n_waves)
        best = max(best, eff[s])
    for s in range(1, max_splits + 1):
        if (s == 1 or math.ceil(num_n_blocks / s) != math.ceil(num_n_blocks / (s - 1))) and eff[s] >= 0.85 * best:
            return s
    return 1

while (active) {
    if (++events > max_events) { status = 1; goto cleanup; }
    double dt_fixed = INFINITY, dt_keys = INFINITY;
    int done_now = 0;
    for (size_t i = 0; i < slots; ++i) {
        rates[i] = 0.0;
        phase[i] = 0;
        if (!occupied[i]) continue;
        if (fixed[i] > EPS_US) {
            phase[i] = 1;
            if (fixed[i] < dt_fixed) dt_fixed = fixed[i];
        } else if (remaining[i] > EPS_KEYS) {
            phase[i] = 2;
            rates[i] = (residents[slot_sm[i]] >= 2 ? gamma : 1.0) / cost;
        } else {
            done_now = 1;
        }
    }
    double demand = pairwise_sum(rates, slots) * bytes_per_key;
    if (!isfinite(demand)) { status = 2; goto cleanup; }
    double scale = demand <= bandwidth ? 1.0 : bandwidth / demand;
    for (size_t i = 0; i < slots; ++i) {
        rates[i] *= scale;
        if (phase[i] == 2) {
            double duration = remaining[i] / rates[i];
            if (duration < dt_keys) dt_keys = duration;
        }
    }
    double dt = done_now ? 0.0 : fmin(dt_fixed, dt_keys);
    elapsed += dt;
    if (scale < 1.0) bw_elapsed += dt;
    if (!isfinite(elapsed) || !isfinite(bw_elapsed) || dt < 0.0) {
        status = 2;
        goto cleanup;
    }
    for (size_t i = 0; i < slots; ++i) {
        if (phase[i] == 1) fixed[i] -= dt;
        if (phase[i] == 2) remaining[i] -= rates[i] * dt;
        if (occupied[i] && fixed[i] <= EPS_US && remaining[i] <= EPS_KEYS) {
            occupied[i] = 0;
            residents[slot_sm[i]]--;
            active--;
            if (next < n) {
                remaining[i] = keys[next++];
                fixed[i] = remaining[i] > 0.0 ? startup : empty;
                occupied[i] = 1;
                residents[slot_sm[i]]++;
                active++;
            }
        }
    }
